function contract(spec) {
  const family = FAMILY_RULES[spec.family];
  if (!family) throw new Error(`Unknown metric-contract family: ${spec.family}`);
  return Object.freeze({
    metric_id: spec.metric_id,
    metric_name: spec.metric_name,
    unit: spec.unit,
    geography: spec.geography || family.geography,
    cadence: spec.cadence || family.cadence,
    observation_time_field: spec.observation_time_field || family.observation_time_field,
    source_id: spec.source_id,
    transformation: spec.transformation || family.transformation,
    uncertainty: spec.uncertainty || family.uncertainty,
    threshold_provenance: spec.threshold_provenance || family.threshold_provenance,
    failure_behavior: spec.failure_behavior || family.failure_behavior,
    reviewed_at: REVIEWED_AT,
    contract_status: 'reviewed_live_node_metric'
  });
}

export const REMAINING_LIVE_NODE_METRIC_CONTRACTS = Object.freeze(
  Object.fromEntries(Object.entries(SPECS).map(([nodeId, spec]) => [nodeId, contract(spec)]))
);
